CREATE TABLE Category (
    category_id         INTEGER  PRIMARY KEY AUTOINCREMENT,
    name                TEXT     NOT NULL,
    parent_category_id  INTEGER,
    FOREIGN KEY (parent_category_id) REFERENCES Category (category_id)
        ON UPDATE CASCADE ON DELETE RESTRICT
);
